import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import 'package:firebase_auth/firebase_auth.dart';

import '../services/storage_service.dart';
import '../services/user_repository.dart';
import '../services/auth_service.dart';
import 'profile_page.dart';

class ProfileDetailsPage extends StatefulWidget {
  static const routeName = '/profile_details';
  const ProfileDetailsPage({super.key});

  @override
  State<ProfileDetailsPage> createState() => _ProfileDetailsPageState();
}

class _ProfileDetailsPageState extends State<ProfileDetailsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightCtrl = TextEditingController();
  final _heightCtrl = TextEditingController();
  final _bodyCtrl = TextEditingController();
  final _picker = ImagePicker();

  File? _photoFile;
  bool _saving = false;

  final _repo = UserRepository();
  final _storage = StorageService();
  final _auth = AuthService();

  @override
  void dispose() {
    _weightCtrl.dispose();
    _heightCtrl.dispose();
    _bodyCtrl.dispose();
    super.dispose();
  }

  Future<void> _pick(ImageSource source) async {
    try {
      final picked = await _picker.pickImage(source: source, imageQuality: 85);
      if (picked != null) {
        setState(() => _photoFile = File(picked.path));
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to pick image: $e')),
      );
    }
  }

  String? _numValidator(String? v, String name) {
    final value = v?.trim() ?? '';
    if (value.isEmpty) return '$name is required';
    final d = double.tryParse(value);
    if (d == null || d <= 0) return 'Enter a valid $name';
    return null;
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;

    final user = _auth.currentUser ?? FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('Not signed in')));
      return;
    }

    setState(() => _saving = true);
    try {
      // 1) Upload optional profile photo to Storage
      String? photoUrl;
      if (_photoFile != null) {
        photoUrl = await _storage.uploadUserProfilePhoto(
          uid: user.uid,
          file: _photoFile!,
        );
      }

      // 2) Parse fields
      final weight = double.parse(_weightCtrl.text.trim());
      final height = double.parse(_heightCtrl.text.trim());
      final bodyType = _bodyCtrl.text.trim();

      // 3) Save to Firestore: keep previously saved name/email; merge new fields
      await _repo.saveUserProfile(
        uid: user.uid,
        email: user.email ?? '',
        weight: weight,
        height: height,
        bodyType: bodyType,
        photoUrl: photoUrl,
        // If your signup saved names already, they will be preserved by merge.
        // Optionally re-send displayName to Auth for consistency:
      );

      // 4) Optionally reflect photo in Firebase Auth profile
      if (photoUrl != null) {
        await _auth.updateProfile(photoURL: photoUrl);
      }

      if (!mounted) return;
      Navigator.pushNamedAndRemoveUntil(
        context,
        ProfilePage.routeName,
        (_) => false,
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to save: $e')),
      );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Profile Details')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // Photo picker
            Center(
              child: Stack(
                children: [
                  CircleAvatar(
                    radius: 56,
                    backgroundColor: Colors.grey.shade300,
                    backgroundImage:
                        _photoFile != null ? FileImage(_photoFile!) : null,
                    child: _photoFile == null
                        ? const Icon(Icons.person, size: 48, color: Colors.white)
                        : null,
                  ),
                  Positioned(
                    bottom: -6,
                    right: -6,
                    child: Row(
                      children: [
                        IconButton(
                          icon: const Icon(Icons.photo, color: Colors.blue),
                          onPressed: () => _pick(ImageSource.gallery),
                          tooltip: 'Pick from gallery',
                        ),
                        IconButton(
                          icon: const Icon(Icons.photo_camera, color: Colors.blue),
                          onPressed: () => _pick(ImageSource.camera),
                          tooltip: 'Take a photo',
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            // Form: weight, height, body type
            Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _weightCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Weight (kg)',
                      hintText: 'e.g. 70',
                    ),
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    validator: (v) => _numValidator(v, 'Weight'),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: _heightCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Height (cm)',
                      hintText: 'e.g. 175',
                    ),
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    validator: (v) => _numValidator(v, 'Height'),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: _bodyCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Body Type',
                      hintText: 'e.g. Athletic',
                    ),
                    validator: (v) {
                      final value = v?.trim() ?? '';
                      if (value.isEmpty) return 'Body type is required';
                      if (value.length < 3) return 'Enter a valid body type';
                      return null;
                    },
                  ),
                ],
              ),
            ),
            const SizedBox(height: 24),
            _saving
                ? const CircularProgressIndicator()
                : SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: _save,
                      icon: const Icon(Icons.check),
                      label: const Text('Save and Continue'),
                    ),
                  ),
          ],
        ),
      ),
    );
  }
}

